-- In-app notification events generated by trusted database triggers.
create or replace function public.notify_betalink_campaign_membership()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  owner_id uuid;
  app_label text;
begin
  select developer_id, app_name into owner_id, app_label
  from public.campaigns where id = new.campaign_id;

  if tg_op = 'INSERT' then
    if owner_id is not null and owner_id <> new.tester_id then
      insert into public.notifications(recipient_id, notification_type, title, body)
      values (owner_id, 'campaign_application', 'Yeni tester başvurusu', app_label || ' kampanyasına yeni bir tester başvurdu.');
    end if;
  elsif old.status is distinct from new.status then
    insert into public.notifications(recipient_id, notification_type, title, body)
    values (
      new.tester_id,
      'application_status',
      'Başvuru durumun güncellendi',
      app_label || ' kampanyasındaki başvurunun durumu: ' || new.status
    );
  end if;
  return new;
end;
$$;

create or replace function public.notify_betalink_group_request()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  owner_id uuid;
  group_label text;
begin
  select created_by, name into owner_id, group_label
  from public.tester_groups where id = new.group_id;
  if new.status = 'pending' and owner_id is not null and owner_id <> new.user_id then
    insert into public.notifications(recipient_id, notification_type, title, body)
    values (owner_id, 'group_request', 'Yeni grup katılım isteği', group_label || ' grubuna katılım isteği geldi.');
  end if;
  return new;
end;
$$;

create or replace function public.notify_betalink_task_submission()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  owner_id uuid;
  app_label text;
  task_label text;
begin
  select c.developer_id, c.app_name, t.title
    into owner_id, app_label, task_label
  from public.campaign_tasks t
  join public.campaigns c on c.id = t.campaign_id
  where t.id = new.task_id;
  if owner_id is not null and owner_id <> new.tester_id then
    insert into public.notifications(recipient_id, notification_type, title, body)
    values (owner_id, 'task_submission', 'Yeni görev teslimi', app_label || ' · ' || task_label);
  end if;
  return new;
end;
$$;

create or replace function public.notify_betalink_feedback()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  owner_id uuid;
  app_label text;
begin
  select developer_id, app_name into owner_id, app_label
  from public.campaigns where id = new.campaign_id;
  if tg_op = 'INSERT' then
    if owner_id is not null and owner_id <> new.tester_id then
      insert into public.notifications(recipient_id, notification_type, title, body)
      values (owner_id, 'new_feedback', 'Yeni tester geri bildirimi', app_label || ' kampanyasına yeni geri bildirim geldi.');
    end if;
  elsif old.developer_reply is distinct from new.developer_reply and new.developer_reply is not null then
    insert into public.notifications(recipient_id, notification_type, title, body)
    values (new.tester_id, 'feedback_reply', 'Geri bildirimin yanıtlandı', app_label || ' kampanyasındaki geri bildirimin yanıtlandı.');
  end if;
  return new;
end;
$$;

revoke all on function public.notify_betalink_campaign_membership() from public, anon, authenticated;
revoke all on function public.notify_betalink_group_request() from public, anon, authenticated;
revoke all on function public.notify_betalink_task_submission() from public, anon, authenticated;
revoke all on function public.notify_betalink_feedback() from public, anon, authenticated;

drop trigger if exists on_betalink_membership_notification on public.campaign_members;
create trigger on_betalink_membership_notification
after insert or update of status on public.campaign_members
for each row execute function public.notify_betalink_campaign_membership();

drop trigger if exists on_betalink_group_request_notification on public.group_members;
create trigger on_betalink_group_request_notification
after insert on public.group_members
for each row execute function public.notify_betalink_group_request();

drop trigger if exists on_betalink_task_submission_notification on public.task_completions;
create trigger on_betalink_task_submission_notification
after insert on public.task_completions
for each row execute function public.notify_betalink_task_submission();

drop trigger if exists on_betalink_feedback_notification on public.feedback;
create trigger on_betalink_feedback_notification
after insert or update of developer_reply on public.feedback
for each row execute function public.notify_betalink_feedback();
